// AG Studio inside an Appsmith custom widget.
// The UMD bundle (~5MB) exposes window.agStudio and carries its own copies of
// ag-grid-enterprise and ag-charts-enterprise, so nothing else is loaded here.
var api = null;
var appliedKey = '';
var lastDataSig = '';
var lastStateKey = -1;
var lastMode = '';

function el(id) { return document.getElementById(id); }

function setStatus(text, kind) {
  var n = el('studio-status');
  if (!n) return;
  n.className = 'status ' + (kind || '');
  n.textContent = text;
}

function rowsOf(model) {
  return (model && Array.isArray(model.rows)) ? model.rows : [];
}

function modeOf(model) {
  return (model && model.mode === 'view') ? 'view' : 'edit';
}

// Cheap signature so we only rebuild Studio when the dataset actually changes.
function dataSignature(model) {
  var rows = rowsOf(model);
  return [model && model.customerId, rows.length, rows.length ? Object.keys(rows[0]).join(',') : ''].join('|');
}

function applyLicense(model) {
  var key = (model && model.licenseKey ? String(model.licenseKey) : '').trim();
  if (!key || key === appliedKey) return;
  if (!window.agStudio || !agStudio.AgStudioLicenseManager) return;
  try {
    agStudio.AgStudioLicenseManager.setLicenseKey(key);
    appliedKey = key;
  } catch (e) {
    console.warn('AG Studio setLicenseKey failed', e);
  }
}

// Reports what AG Studio thinks of the supplied key. getLicenseDetails is marked
// internal, so any failure here is non-fatal — Studio still renders, watermarked.
function describeLicense(model) {
  var key = (model && model.licenseKey ? String(model.licenseKey) : '').trim();
  if (!key) return 'no licence key set — running unlicensed (watermarked)';
  try {
    var d = agStudio.AgStudioLicenseManager.getLicenseDetails(key, new Set());
    if (!d) return 'licence key applied';
    if (d.valid && !d.expired) {
      return 'licence OK' + (d.isTrial ? ' (trial)' : '') + (d.expiry ? ', expires ' + d.expiry : '');
    }
    if (d.incorrectLicenseType) {
      return 'WRONG LICENCE TYPE — supplied ' + (d.suppliedLicenseType || 'unknown') +
             ', Studio needs ' + (d.currentLicenseType || 'STUDIO-*');
    }
    if (d.expired) return 'licence expired' + (d.expiry ? ' on ' + d.expiry : '');
    return 'licence not valid for AG Studio';
  } catch (e) {
    return 'licence key applied (could not verify)';
  }
}


// Dark theme built off studioTheme, matching the palette the Analytics page
// already uses for its ECharts widgets (#0F172A / #1E293B / #334155 / #E2E8F0).
var DARK = {
  // --- shared: most other colours are derived from these -------------------
  browserColorScheme: 'dark',
  foregroundColor: '#E2E8F0',
  backgroundColor: '#1E293B',
  chromeBackgroundColor: '#1E293B',
  accentColor: '#3B82F6',
  borderColor: '#334155',
  textColor: '#E2E8F0',
  subtleTextColor: '#94A3B8',
  iconColor: '#CBD5E1',
  invalidColor: '#F08A8A',
  headerBackgroundColor: '#1E293B',
  headerTextColor: '#E2E8F0',
  menuBackgroundColor: '#1E293B',
  menuTextColor: '#E2E8F0',
  menuSeparatorColor: '#334155',

  // --- studio chrome -------------------------------------------------------
  studioFormLabelColor: '#CBD5E1',
  studioWrapperBackgroundColor: '#0F172A',
  studioPanelContainerBackgroundColor: '#1E293B',
  studioPanelBackgroundColor: '#1E293B',
  studioPanelDividerColor: '#334155',
  studioPanelDividerActiveColor: '#3B82F6',
  studioPanelSectionBorderColor: '#334155',
  studioPanelGroupBackgroundColor: '#1E293B',
  // AG Studio also uses this token as the text colour of a disabled group
  // label (e.g. "Border" when its toggle is off), and its background role is
  // not visible in this layout — so it is set to a readable muted slate.
  studioPanelGroupTitleBarBackgroundColor: '#94A3B8',
  studioPanelTabHeaderBackgroundColor: '#0F172A',
  studioPanelTabHeaderSelectedBackgroundColor: '#1E293B',
  studioPanelChevronButtonHoverBackgroundColor: '#334155',
  studioPanelChevronButtonHoverColor: '#E2E8F0',
  studioCanvasBackgroundColor: '#0F172A',
  studioPanelWidth: 230,

  // --- inputs and pickers --------------------------------------------------
  inputBackgroundColor: '#0F172A',
  inputTextColor: '#E2E8F0',
  inputBorder: [1, '#334155'],
  inputPlaceholderTextColor: '#64748B',
  inputIconColor: '#94A3B8',
  inputFocusBorder: [1, '#3B82F6'],
  inputDisabledBackgroundColor: '#172033',
  inputDisabledTextColor: '#64748B',
  pickerButtonBackgroundColor: '#0F172A',
  pickerButtonBorder: [1, '#334155'],
  pickerListBackgroundColor: '#1E293B',
  pickerListBorder: [1, '#334155'],

  // --- buttons (the widget toolbar actions live here) ----------------------
  buttonTextColor: '#E2E8F0',
  buttonBackgroundColor: '#243244',
  buttonBorder: [1, '#334155'],
  buttonHoverTextColor: '#F1F5F9',
  buttonHoverBackgroundColor: '#334155',
  buttonActiveTextColor: '#FFFFFF',
  buttonActiveBackgroundColor: '#3B82F6',
  buttonDisabledTextColor: '#64748B',
  buttonDisabledBackgroundColor: '#172033',

  // --- checkboxes and toggles ----------------------------------------------
  checkboxUncheckedBackgroundColor: '#0F172A',
  checkboxUncheckedBorderColor: '#475569',
  checkboxCheckedBackgroundColor: '#3B82F6',
  checkboxCheckedBorderColor: '#3B82F6',
  checkboxCheckedShapeColor: '#0F172A',

  // --- tabs (Widgets / Page) -----------------------------------------------
  tabBarBackgroundColor: '#0F172A',
  tabBarBorder: [1, '#334155'],
  tabTextColor: '#94A3B8',
  tabHoverTextColor: '#E2E8F0',
  tabSelectedTextColor: '#E2E8F0',
  tabSelectedBackgroundColor: '#1E293B',
  tabSelectedUnderlineColor: '#3B82F6',

  // --- widget surfaces -----------------------------------------------------
  studioWidgetBackgroundColor: '#1E293B',
  studioWidgetBorder: [1, '#334155'],
  studioWidgetTitleTextColor: '#E2E8F0',
  studioWidgetSubtitleTextColor: '#94A3B8',
  studioWidgetCaptionTextColor: '#94A3B8',

  studioToggleButtonActiveBackgroundColor: '#3B82F6',
  studioToggleButtonActiveBorderColor: '#3B82F6',
  studioToggleButtonActiveColor: '#3B82F6',

  studioDragAndDropImageTextColor: '#E2E8F0',
  studioDragAndDropImageIconColor: '#E2E8F0',
  studioDragAndDropImageBackgroundColor: '#1E293B',
  studioDragAndDropImageBorder: [1, '#334155'],
  studioDragAndDropImageNotAllowedTextColor: '#E2E8F0',
  studioDragAndDropImageNotAllowedIconColor: '#E2E8F0',
  studioDragAndDropImageNotAllowedBackgroundColor: '#1E293B',
  studioDragAndDropImageNotAllowedBorder: [1, '#F08A8A'],

  // --- widget hover toolbar (settings / export / duplicate / close) --------
  studioWidgetToolbarBackgroundColor: '#1E293B',
  studioWidgetToolbarBorder: [1, '#334155'],
  studioWidgetToolbarButtonColor: '#CBD5E1',
  studioWidgetToolbarButtonHoverBackgroundColor: '#334155',
  studioWidgetToolbarButtonDisabledBackgroundColor: '#172033',
  studioWidgetResizeBorderColor: '#3B82F6',
  studioWidgetSelectIconBackgroundColor: '#3B82F6',
  studioWidgetLoadingOverlayBackgroundColor: 'rgba(15, 23, 42, 0.6)',
  studioWidgetNoDataOverlayBackgroundColor: 'rgba(15, 23, 42, 0.6)',

  // --- canvas and drag affordances ----------------------------------------
  studioCanvasGridLineColor: '#1E293B',
  studioCanvasDragPreviewBackgroundColor: '#243244',
  studioFieldSelectDropPreviewBackgroundColor: '#243244',
  studioFieldSelectReplaceBackgroundColor: '#334155',
  dragAndDropImageBackgroundColor: '#1E293B',

  // --- filters panel -------------------------------------------------------
  studioFiltersPanelWarnBackgroundColor: '#3B2E1A',
  studioFiltersPanelCardSubtleColor: '#94A3B8',
  studioFiltersPanelCardSubtleHoverColor: '#E2E8F0',

  // --- toggles and tooltips ------------------------------------------------
  toggleButtonOffBackgroundColor: '#475569',
  toggleButtonOnBackgroundColor: '#3B82F6',
  toggleButtonSwitchBackgroundColor: '#E2E8F0',
  tooltipBackgroundColor: '#1E293B',
  tooltipTextColor: '#E2E8F0',
  tooltipErrorBackgroundColor: '#3B1D1D',
  tooltipErrorTextColor: '#F08A8A',

  // --- grid and chart internals --------------------------------------------
  gridRowBorder: [1, '#334155'],
  gridHeaderRowBorder: [2, '#334155'],
  gridPinnedRowBorder: [2, '#334155'],

  chartTextColor: '#E2E8F0',
  chartSubtleTextColor: '#94A3B8',
  chartAxisLineColor: '#475569',
  chartGridLineColor: '#334155'
};

function darkTheme() {
  try {
    return agStudio.studioTheme.withParams(DARK);
  } catch (e) {
    console.warn('dark theme failed, falling back to default', e);
    return undefined;
  }
}

function statusLine(model) {
  var n = rowsOf(model).length.toLocaleString();
  var mode = modeOf(model) === 'view' ? 'view mode (read only)' : 'edit mode';
  return n + ' rows · ' + mode + ' · ' + describeLicense(model);
}

function buildStudio(model) {
  var root = el('studio-root');
  if (!root) return;
  var rows = rowsOf(model);

  if (api && typeof api.destroy === 'function') {
    try { api.destroy(); } catch (e) { /* already gone */ }
  }
  api = null;
  root.innerHTML = '';

  if (rows.length === 0) {
    setStatus('No rows returned for this customer.', 'warn');
    return;
  }

  var props = {
    mode: modeOf(model),
    theme: darkTheme(),
    // Fields are inferred from the row data when not supplied.
    data: {
      sources: [{
        id: 'monthly_usage',
        name: (model && model.customerName ? model.customerName + ' — ' : '') + 'Monthly Usage',
        description: 'Monthly billed usage and charges per location, utility and vendor.',
        data: rows
      }]
    },
    dataOptions: { maxExportRows: -1 },
    onStudioReady: function () {
      setStatus(statusLine(model), 'ok');
    },
    onErrorRaised: function (ev) {
      console.error('AG Studio error', ev);
      setStatus('Studio error: ' + ((ev && ev.message) || 'see console'), 'err');
    },
    // Surface report state so a Save button can persist it via storeValue.
    onStateUpdated: function (ev) {
      if (!appsmith.updateModel) return;
      try {
        appsmith.updateModel({ reportState: (ev && ev.state) || (api && api.getState && api.getState()) || null });
      } catch (e) { /* non-fatal */ }
    }
  };

  if (model && model.savedState) props.initialState = model.savedState;

  try {
    api = agStudio.createStudio(root, props);
    setStatus('Starting AG Studio…');
  } catch (e) {
    console.error(e);
    setStatus('createStudio failed: ' + (e && e.message), 'err');
  }
}

function render(model) {
  if (!window.agStudio || !agStudio.createStudio) {
    setStatus('AG Studio bundle did not load — check the CDN script tag.', 'err');
    return;
  }
  applyLicense(model);

  var sig = dataSignature(model);
  var stateKey = Number(model && model.stateKey) || 0;
  var mode = modeOf(model);

  if (sig === lastDataSig && stateKey === lastStateKey) {
    if (api && mode !== lastMode) {
      lastMode = mode;
      try {
        api.setProperty('mode', mode);
        setStatus(statusLine(model), 'ok');
      } catch (e) {
        console.warn('mode switch failed, rebuilding', e);
        buildStudio(model);
      }
    }
    return;
  }

  lastDataSig = sig;
  lastStateKey = stateKey;
  lastMode = mode;
  buildStudio(model);
}

// The bundle is large; poll briefly for the global before first render.
function whenReady(model, tries) {
  if (window.agStudio && agStudio.createStudio) { render(model); return; }
  if (tries <= 0) {
    setStatus('Timed out waiting for the AG Studio bundle (~5MB). Reload the page.', 'err');
    return;
  }
  setStatus('Loading AG Studio bundle…');
  setTimeout(function () { whenReady(model, tries - 1); }, 250);
}

appsmith.onReady(function () {
  whenReady(appsmith.model, 160);

  appsmith.onModelChange(function (model) {
    if (window.agStudio && agStudio.createStudio) render(model);
  });
});

